def is_good_triple(x, y, z):
    # Check if (x+1)^y is divisible by x^z + 1
    try:
        numerator = (x + 1)**y
        denominator = x**z + 1
        if denominator <= 0:
            return False
        return numerator % denominator == 0
    except OverflowError:
        return False

def count_good_triples_subset(max_x, max_val):
    count = 0
    # Constraints: 1 <= x <= max_x, 1 <= y <= max_val, 1 <= z <= max_val
    for x in range(1, max_x + 1):
        for y in range(1, max_val + 1):
            for z in range(1, max_val + 1):
                if is_good_triple(x, y, z):
                    count += 1
    return count

