def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

solutions = set()

# Case x = 1
for z in range(1, 100):
    solutions.add((1, z))

# Case z = 1
for x in range(2, 100):
    # Check if x + 1 is a power of 2
    if is_power_of_two(x + 1):
        solutions.add((x, 1))

# Case x >= 2 and z >= 2
for x in range(2, 100):
    # Check up to z=99. We need to handle potential overflow checks internally if needed,
    # but Python handles large integers.
    for z in range(2, 100):
        try:
            n = x**z + 1
            if is_power_of_two(n):
                solutions.add((x, z))
        except OverflowError:
            # Should not happen with standard Python integers unless the exponent is astronomical
            break

print("Found pairs (x, z) such that x^z + 1 is a power of 2:")
for x, z in sorted(list(solutions)):
    print(f"({x}, {z})")

# Verification of solutions found:
# (1, z) for 1<=z<=99
# (2^k - 1, 1) for 2^k - 1 < 100 (x=3, 7, 15, 31, 63, 1)
# We look for specific cases like x=3, z=2. 3^2+1=10 (not power of 2).
# x=2, z=2. 2^2+1=5 (not power of 2).
# x=2, z=3. 2^3+1=9 (not power of 2).
# The only other known solutions to x^z+1=2^k besides the trivial ones are related to Catalan's conjecture, 
# but in this strict boundary, we rely on the search.

def is_good_triple(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1
    # Since x, y, z are positive integers, numerator and denominator are positive integers.
    # We check if the division results in an integer.
    return numerator % denominator == 0

count = 0
limit = 99
for x in range(1, limit + 1):
    for y in range(1, limit + 1):
        for z in range(1, limit + 1):
            if is_good_triple(x, y, z):
                count += 1
print(f"Total number of good triples (x,y,z) with 1 <= x, y, z <= 99: {count}")
